parameters.jsCode:
const fs = require('fs');
const p = $('When Executed by Another Workflow').first().json;
let concept = null;
try {
  const text = $input.first().json.candidates[0].content.parts.map((x) => x.text || '').join('');
  concept = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) { concept = null; }
// 컨셉 실패 시 밈 없이 데이터 표지로 진행 (발행은 멈추지 않는다)
if (!concept || !concept.imagePrompt) return [{ json: { ...p, skip: true } }];
const code = (concept.driverCode || '').toLowerCase().replace(/[^a-z]/g, '');
let refPath = null, needChar = false;
if (code) {
  const dir = '/data/hooni_speed/assets/characters/' + code;
  for (const f of ['base.png', '_pending.png']) {
    try { if (fs.statSync(dir + '/' + f).size > 0) { refPath = dir + '/' + f; break; } } catch (e) {}
  }
  if (!refPath) {
    try { const poses = fs.readdirSync(dir + '/poses'); if (poses.length) refPath = dir + '/poses/' + poses[0]; } catch (e) {}
  }
  needChar = !refPath;
}
return [{ json: { ...p, concept, driverCode: code || null, refPath, needChar, skip: false } }];

const fs = require('fs');
const p = $('Parse Concept').first().json;
const parts = ((($input.first().json.candidates || [])[0] || {}).content || {}).parts || [];
const img = parts.find((x) => x.inlineData || x.inline_data);
if (!img) return [{ json: { ...p, refPath: null } }]; // 캐릭터 생성 실패 → 레퍼런스 없이 표지 생성
const d = img.inlineData || img.inline_data;
const dir = '/data/hooni_speed/assets/characters/' + p.driverCode;
fs.mkdirSync(dir, { recursive: true });
const out = dir + '/_pending.png';
fs.writeFileSync(out, Buffer.from(d.data, 'base64'));
return [{ json: { ...p, refPath: out, charPending: out } }];

const fs = require('fs');
const p = $input.first().json;
const parts = [];
if (p.refPath) {
  try { parts.push({ inlineData: { mimeType: 'image/png', data: fs.readFileSync(p.refPath).toString('base64') } }); } catch (e) {}
}
const ref = p.refPath ? ' Keep the exact same character identity and art style as the reference image.' : '';
parts.push({ text: p.concept.imagePrompt + ref + ' Consistent art style: flat vector cartoon illustration, bold clean outlines, simple cel shading, vivid saturated colors, no text, no watermark, no logos' });
return [{ json: { ...p, geminiBody: { contents: [{ parts }], generationConfig: { responseModalities: ['IMAGE'] } } } }];

const fs = require('fs');
const p = $('Build Image Req').first().json;
const cards = JSON.parse(JSON.stringify(p.cards));
const parts = ((($input.first().json.candidates || [])[0] || {}).content || {}).parts || [];
const img = parts.find((x) => x.inlineData || x.inline_data);
if (img) {
  const d = img.inlineData || img.inline_data;
  const dir = '/data/hooni_speed/assets/meme';
  fs.mkdirSync(dir, { recursive: true });
  const out = dir + '/' + p.season + '-r' + p.round + '-' + p.dayType + '.png';
  fs.writeFileSync(out, Buffer.from(d.data, 'base64'));
  cards[0].data = { ...cards[0].data, bgFile: out };
}
// 이미지가 없어도 카피는 반영 (데이터 표지로 렌더)
if (p.concept.title) cards[0].data.title = p.concept.title;
if (p.concept.subtitle) cards[0].data.subtitle = p.concept.subtitle;
const out = { ...p, cards };
delete out.geminiBody;
return [{ json: out }];
